import java.io.InputStream;
import java.io.IOException;
import java.util.Arrays;

public class Main {
    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int n = scanner.nextInt();
        int k = scanner.nextInt();
        int c = scanner.nextInt();

        long[] a = new long[n];
        long totalSum = 0;
        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
            totalSum += a[i];
        }

        if (c == 1) {
            Arrays.sort(a);
            long coveredSum = 0;
            for (int i = 0; i < k; i++) {
                coveredSum += a[i];
            }
            System.out.println(totalSum - coveredSum);
            return;
        }

        long[] pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i] + a[i];
        }

        long[] prevDp = new long[n + 1];
        long[] currDp = new long[n + 1];

        // dp[j][i]: menor soma ao colocar j etiquetas nos primeiros i elementos
        for (int j = 1; j <= k; j++) {
            int minI = j * c;
            // Para i < minI, o estado é inalcançável (armazenamos infinito)
            for (int i = 0; i < minI; i++) {
                currDp[i] = Long.MAX_VALUE / 2;
            }
            for (int i = minI; i <= n; i++) {
                long segSum = pref[i] - pref[i - c];
                long option1 = currDp[i - 1];
                long option2 = prevDp[i - c] + segSum;
                currDp[i] = Math.min(option1, option2);
            }
            long[] temp = prevDp;
            prevDp = currDp;
            currDp = temp;
        }

        long minCovered = prevDp[n];
        System.out.println(totalSum - minCovered);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private byte read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            byte c = read();
            while (c <= ' ' && c != -1) {
                c = read();
            }
            if (c == -1) return -1;
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = read();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = read();
            }
            return neg ? -res : res;
        }
    }
}
